parameters.functionCode:
// Extract campaign results and prepare for next steps
const output = $input.item.json;

return {
  campaign_id: output.campaign_id,
  company: output.company,
  profiles_count: output.profiles_scraped,
  messages_count: output.messages_generated,
  avg_message_length: output.avg_message_length,
  files: output.files_created,
  workflow_file: output.files_created.find(f => f.includes('workflow')),
  messages_file: output.files_created.find(f => f.includes('messages')),
  report_file: output.files_created.find(f => f.includes('report')),
  ai_powered: output.ai_powered
};

